package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type LedgerRec struct { // 01 LEDGER-REC, 14 bytes
	BrBranch string          // PIC X(2) @0 len=2
	BrAcct   string          // PIC X(4) @2 len=4
	BrType   string          // PIC X(1) @6 len=1
	BrAmt    decimal.Decimal // PIC 9(5)V99 @7 len=7
}

// Standalone working-storage items (VALUE shown after '=')
var WsEofFlag string = "N"  // PIC X len=1 = "N"
var WsFirstFlag string = "Y" // PIC X len=1 = "Y"
var WsPrevBranch string = "  "
var WsPrevAcct string = "    "
var WsBal decimal.Decimal = decimal.New(0, 0)
var WsBranchTot decimal.Decimal = decimal.New(0, 0)
var WsGrandTot decimal.Decimal = decimal.New(0, 0)
var WsSkipped int64 = 0
var WsAmtEd string
var WsBalEd string
var WsTotEd string

var BrBranch string
var BrAcct string
var BrType string
var BrAmt decimal.Decimal

var ledgerRecords []LedgerRec
var ledgerIdx int

func pow10Int64(n int) int64 {
	if n == 0 {
		return 1
	}
	var p int64 = 1
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func truncateToPic(v decimal.Decimal, intDigits int, scale int) decimal.Decimal {
	if v.IsZero() {
		return decimal.New(0, 0)
	}
	scaled := v.Shift(int32(scale))
	scaledTrunc := scaled.Truncate(0)
	scaledInt := scaledTrunc.IntPart()
	powTotal := pow10Int64(intDigits + scale)
	mod := scaledInt % powTotal
	res := decimal.New(mod, -int32(scale))
	if res.IsZero() {
		return decimal.New(0, 0)
	}
	return res
}

func truncateBal(v decimal.Decimal) decimal.Decimal {
	return truncateToPic(v, 7, 2)
}
func truncateBranchTot(v decimal.Decimal) decimal.Decimal {
	return truncateToPic(v, 9, 2)
}
func truncateGrandTot(v decimal.Decimal) decimal.Decimal {
	return truncateToPic(v, 9, 2)
}

func formatEdited(v decimal.Decimal, picture string) string {
	isSigned := strings.HasPrefix(picture, "-")
	var picBody string
	var signChar rune
	if isSigned {
		picBody = picture[1:]
		if v.Sign() < 0 {
			signChar = '-'
		} else {
			signChar = ' '
		}
	} else {
		picBody = picture
	}
	dotIdx := strings.Index(picBody, ".")
	var intPic, fracPic string
	if dotIdx >= 0 {
		intPic = picBody[:dotIdx]
		fracPic = picBody[dotIdx+1:]
	} else {
		intPic = picBody
		fracPic = ""
	}
	intSlots := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intSlots++
		}
	}
	scale := len(fracPic)
	absVal := v.Abs()
	scaled := absVal.Shift(int32(scale))
	scaled = scaled.Truncate(0)
	scaledInt := scaled.IntPart()
	powScale := pow10Int64(scale)
	var intPart, fracPart int64
	if powScale == 0 {
		powScale = 1
	}
	intPart = scaledInt / powScale
	fracPart = scaledInt % powScale
	if intSlots > 0 {
		powInt := pow10Int64(intSlots)
		intPart = intPart % powInt
	}
	intStr := fmt.Sprintf("%0*d", intSlots, intPart)
	fracStr := ""
	if scale > 0 {
		fracStr = fmt.Sprintf("%0*d", scale, fracPart)
	}
	outInt := make([]rune, len(intPic))
	digitIdx := 0
	for i, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			outInt[i] = rune(intStr[digitIdx])
			digitIdx++
		} else {
			outInt[i] = ch
		}
	}
	suppressed := true
	for i, ch := range intPic {
		if ch == 'Z' {
			if outInt[i] == '0' && suppressed {
				outInt[i] = ' '
			} else {
				suppressed = false
			}
		} else if ch == '9' {
			suppressed = false
		} else if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		}
	}
	var res string
	if dotIdx >= 0 {
		res = string(outInt) + "." + fracStr
	} else {
		res = string(outInt)
	}
	if isSigned {
		res = string(signChar) + res
	}
	return res
}

func formatAmt(v decimal.Decimal) string {
	return formatEdited(v, "ZZ,ZZ9.99")
}
func formatBal(v decimal.Decimal) string {
	return formatEdited(v, "-Z,ZZZ,ZZ9.99")
}
func formatTot(v decimal.Decimal) string {
	return formatEdited(v, "-ZZZ,ZZZ,ZZ9.99")
}

func isInputDone() bool { return WsEofFlag == "Y" }
func isFirstRecord() bool { return WsFirstFlag == "Y" }

func parseLedgerRec(line string) LedgerRec {
	if len(line) < 14 {
		line = line + strings.Repeat(" ", 14-len(line))
	} else if len(line) > 14 {
		line = line[:14]
	}
	brBranch := line[0:2]
	brAcct := line[2:6]
	brType := line[6:7]
	brAmtStr := line[7:14]
	var amt decimal.Decimal
	trimmed := strings.TrimSpace(brAmtStr)
	if trimmed == "" {
		amt = decimal.New(0, 0)
	} else {
		digits := ""
		for _, ch := range brAmtStr {
			if ch >= '0' && ch <= '9' {
				digits += string(ch)
			} else if ch == ' ' {
				digits += "0"
			}
		}
		if digits == "" {
			digits = "0"
		}
		n, err := strconv.ParseInt(digits, 10, 64)
		if err != nil {
			n = 0
		}
		amt = decimal.New(n, -2)
	}
	return LedgerRec{BrBranch: brBranch, BrAcct: brAcct, BrType: brType, BrAmt: amt}
}

func loadLedgerFile() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			ledgerRecords = []LedgerRec{}
			return
		}
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	if len(data) == 0 {
		ledgerRecords = []LedgerRec{}
		return
	}
	content := string(data)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	lines := strings.Split(content, "\n")
	if len(content) > 0 && content[len(content)-1] == '\n' {
		if len(lines) > 0 && lines[len(lines)-1] == "" {
			lines = lines[:len(lines)-1]
		}
	}
	if len(lines) == 1 && lines[0] == "" && content == "" {
		ledgerRecords = []LedgerRec{}
		return
	}
	ledgerRecords = make([]LedgerRec, 0, len(lines))
	for _, line := range lines {
		rec := parseLedgerRec(line)
		ledgerRecords = append(ledgerRecords, rec)
	}
}

func readPara() {
	if ledgerIdx >= len(ledgerRecords) {
		WsEofFlag = "Y"
		return
	}
	rec := ledgerRecords[ledgerIdx]
	ledgerIdx++
	BrBranch = rec.BrBranch
	BrAcct = rec.BrAcct
	BrType = rec.BrType
	BrAmt = rec.BrAmt
}

func postPara() {
	WsAmtEd = formatAmt(BrAmt)
	switch BrType {
	case "D":
		WsBal = truncateBal(WsBal.Add(BrAmt))
		fmt.Println(BrAcct + " D " + WsAmtEd)
	case "C":
		WsBal = truncateBal(WsBal.Sub(BrAmt))
		fmt.Println(BrAcct + " C " + WsAmtEd)
	default:
		WsSkipped = (WsSkipped + 1) % 100
		fmt.Println(BrAcct + " ? SKIPPED")
	}
}

func acctBreakPara() {
	WsBalEd = formatBal(WsBal)
	fmt.Println("  ACCOUNT " + WsPrevAcct + " BALANCE:" + WsBalEd)
	WsBranchTot = truncateBranchTot(WsBranchTot.Add(WsBal))
	WsBal = decimal.New(0, 0)
}

func branchBreakPara() {
	WsTotEd = formatTot(WsBranchTot)
	fmt.Println(" BRANCH " + WsPrevBranch + " TOTAL:" + WsTotEd)
	WsGrandTot = truncateGrandTot(WsGrandTot.Add(WsBranchTot))
	WsBranchTot = decimal.New(0, 0)
}

func grandPara() {
	WsTotEd = formatTot(WsGrandTot)
	fmt.Println("GRAND TOTAL:" + WsTotEd)
	skippedStr := fmt.Sprintf("%02d", WsSkipped)
	fmt.Println("SKIPPED: " + skippedStr)
}

func processPara() {
	if isFirstRecord() {
		WsPrevBranch = BrBranch
		WsPrevAcct = BrAcct
		WsFirstFlag = "N"
	} else {
		if BrBranch != WsPrevBranch {
			acctBreakPara()
			branchBreakPara()
			WsPrevBranch = BrBranch
			WsPrevAcct = BrAcct
		} else {
			if BrAcct != WsPrevAcct {
				acctBreakPara()
				WsPrevAcct = BrAcct
			}
		}
	}
	postPara()
	readPara()
}

func mainPara() {
	loadLedgerFile()
	readPara()
	for !isInputDone() {
		processPara()
	}
	if !isFirstRecord() {
		acctBreakPara()
		branchBreakPara()
	}
	grandPara()
}

func main() {
	mainPara()
}
